<script setup lang="ts">import{onMounted,reactive,ref}from"vue";import{modelConfigsApi,type ModelConfig}from"../../api/modelConfigs";const items=ref<ModelConfig[]>([]);const message=ref("");const form=reactive({deployment_mode:"local",provider:"ollama",api_base:"http://localhost:11434",api_key:"",model_name:"",is_default:true,allow_cloud_content:false});async function load(){items.value=await modelConfigsApi.list()}async function save(){await modelConfigsApi.create(form);form.api_key="";await load()}async function test(item:ModelConfig){const cloud=item.provider!=="ollama";if(cloud&&!confirm("连接测试可能产生少量云端费用，是否继续？"))return;message.value=(await modelConfigsApi.test(item.id,cloud)).message}async function remove(id:number){await modelConfigsApi.remove(id);await load()}onMounted(load)</script>
<template><main class="settings"><header><p>PRIVACY FIRST</p><h1>模型与数据外发设置</h1><p>完全本地模式不会自动切换云端。云端或混合模式必须明确授权内容外发。</p></header><form @submit.prevent="save"><select v-model="form.deployment_mode"><option value="local">完全本地</option><option value="cloud">云端</option><option value="hybrid">混合</option></select><select v-model="form.provider"><option value="ollama">Ollama</option><option value="openai">OpenAI</option><option value="openrouter">OpenRouter</option></select><input v-model="form.api_base" placeholder="API Base" required/><input v-model="form.model_name" placeholder="Model Name" required/><input v-if="form.provider!=='ollama'" v-model="form.api_key" type="password" autocomplete="new-password" placeholder="API Key（保存后不回显）"/><label v-if="form.deployment_mode!=='local'" class="privacy"><input v-model="form.allow_cloud_content" type="checkbox"/>我授权将提问与检索内容发送至所选云端 Provider</label><label><input v-model="form.is_default" type="checkbox"/>设为默认</label><button>保存配置</button></form><p>{{message}}</p><section><article v-for="item in items" :key="item.id"><b>{{item.provider}} · {{item.model_name}}</b><span>{{item.deployment_mode==='local'?'完全本地':'内容可能外发'}}</span><code>{{item.api_key_masked||'无需密钥'}}</code><button @click="test(item)">测试连接</button><button @click="remove(item.id)">删除</button></article></section></main></template>
<style scoped>.settings{max-width:940px;margin:auto;padding:4rem 1rem}h1{font:700 3.4rem Georgia,serif;color:#173f3c}form{display:grid;grid-template-columns:repeat(2,1fr);gap:.7rem;padding:1.2rem;background:#fff;border-radius:16px}input,select,button{padding:.7rem;border:1px solid #9cafaa;border-radius:8px}.privacy{grid-column:1/-1;padding:.7rem;background:#fff0d2}section{display:grid;gap:.7rem;margin-top:1rem}article{display:flex;align-items:center;gap:.7rem;padding:1rem;background:white;border-radius:12px}article b{margin-right:auto}button{background:#173f3c;color:white;font-weight:700}</style>
